pm.test("Status is 200", () => pm.response.to.have.status(200));

const body = pm.response.json();
const classes = [
  "Front Breakage", "Front Crushed", "Front Normal",
  "Rear Breakage", "Rear Crushed", "Rear Normal",
];

pm.test("Response has exactly the three contract fields", () => {
  pm.expect(body).to.have.all.keys("prediction", "confidence", "probabilities");
});

pm.test("Prediction is one of the six classes", () => {
  pm.expect(classes).to.include(body.prediction);
});

pm.test("Probabilities cover all six classes and sum to 1", () => {
  pm.expect(Object.keys(body.probabilities)).to.have.members(classes);
  const total = Object.values(body.probabilities).reduce((a, b) => a + b, 0);
  pm.expect(total).to.be.closeTo(1, 0.01);
});

pm.test("Prediction and confidence agree with the probabilities", () => {
  const [topClass, topProbability] = Object.entries(body.probabilities)
    .sort((a, b) => b[1] - a[1])[0];
  pm.expect(body.prediction).to.eql(topClass);
  pm.expect(body.confidence).to.eql(topProbability);
});

pm.test("A file that only claims to be a JPEG is rejected", () =>
  pm.response.to.have.status(400));

pm.test("Error says the image could not be read", () => {
  pm.expect(pm.response.json().detail).to.include("readable image");
});

pm.test("A request with no file is rejected", () => pm.response.to.have.status(422));

pm.test("Error names the missing field", () => {
  const detail = JSON.stringify(pm.response.json().detail);
  pm.expect(detail).to.include("file");
  pm.expect(detail).to.include("missing");
});
